-- Exercise 08
-- a
-- deliveries: Retrieve the code, farm, collection point, time of receipt, coffee type, and gross weight for the deliveries made that day (use `LIKE` on the delivery ID), using the aliases `delivery`, `farm id`, `collection point id`, `received at`, `coffee type`, and `gross weight kg`, ordered by the time of receipt.

SELECT
    T1.delivery_id AS delivery,
    T1.farm_id AS farm_id,
    T1.collection_point_id AS collection_point_id,
    T1.delivered_at AS received_at,
    T1.coffee_type AS coffee_type,
    T1.gross_weight_kg AS gross_weight_kg
FROM buy.deliveries AS T1
WHERE T1.delivery_id LIKE 'DLV-20260930-%'
ORDER BY T1.delivered_at ASC;

